204:000204 | 	void writeDownload(HttpServletResponse response, String fileName, String contentType, byte[] content) throws Exception {
205:000205 | 		String encoded = URLEncoder.encode(fileName, "UTF-8").replace("+", "%20");
206:000206 | 		response.reset();
207:000207 | 		response.setContentType(contentType);
208:000208 | 		response.setHeader("Content-Disposition", "attachment; filename=download; filename*=UTF-8''" + encoded);
209:000209 | 		response.setContentLength(content.length);
210:000210 | 		response.getOutputStream().write(content);
211:000211 | 		response.getOutputStream().flush();
212:000212 | 	}
