32:    static Connection openConnection() throws SQLException {
33:        DataSource dataSource = businessCached;
34:        if (dataSource == null) {
35:            synchronized (NenkinDataSource.class) {
36:                dataSource = businessCached;
37:                if (dataSource == null) {
