47:    static Connection openStaffConnection() throws SQLException {
48:        DataSource dataSource = staffCached;
49:        if (dataSource == null) {
50:            synchronized (NenkinDataSource.class) {
51:                dataSource = staffCached;
52:                if (dataSource == null) {
53:                    dataSource = lookup(STAFF_JNDI_NAMES,
54:                            "N2職員名簿用JNDI DataSourceを取得できません。");
55:                    staffCached = dataSource;
56:                }
57:            }
58:        }
59:        return dataSource.getConnection();
60:    }
