62:    static Connection openCustomerConnection() throws SQLException {
63:        DataSource dataSource = customerCached;
64:        if (dataSource == null) {
65:            synchronized (NenkinDataSource.class) {
66:                dataSource = customerCached;
67:                if (dataSource == null) {
68:                    dataSource = lookup(CUSTOMER_JNDI_NAMES,
69:                            "N2顧客基本表用JNDI DataSourceを取得できません。");
70:                    customerCached = dataSource;
71:                }
72:            }
73:        }
74:        return dataSource.getConnection();
