77:    private static DataSource lookup(String[] jndiNames, String message) throws SQLException {
78:        NamingException last = null;
79:        for (int i = 0; i < jndiNames.length; i++) {
80:            try {
81:                Object value = new InitialContext().lookup(jndiNames[i]);
82:                if (value instanceof DataSource) {
83:                    return (DataSource) value;
84:                }
85:            } catch (NamingException e) {
86:                last = e;
87:            }
88:        }
89:        SQLException failure = new SQLException(message);
90:        if (last != null) {
91:            failure.initCause(last);
92:        }
93:        throw failure;
94:    }
