78:000078 | 	private void initializeDatabase(ServletContext context) throws Exception {
79:000079 | 		Connection connection = null;
80:000080 | 		try {
81:000081 | 			connection = dataSource.getConnection();
82:000082 | 			runScript(context, connection, "/WEB-INF/resources/db/schema.sql");
83:000083 | 			runScript(context, connection, "/WEB-INF/resources/db/data.sql");
84:000084 | 		} finally {
85:000085 | 			if (connection != null) connection.close();
86:000086 | 		}
87:000087 | 	}
