89:000089 | 	private void runScript(ServletContext context, Connection connection, String path) throws Exception {
90:000090 | 		InputStream stream = context.getResourceAsStream(path);
91:000091 | 		if (stream == null) throw new IllegalStateException("Database resource not found: " + path);
92:000092 | 		Reader reader = null;
93:000093 | 		try {
94:000094 | 			reader = new InputStreamReader(stream, "UTF-8");
95:000095 | 			RunScript.execute(connection, reader);
96:000096 | 		} finally {
97:000097 | 			if (reader != null) reader.close(); else stream.close();
98:000098 | 		}
99:000099 | 	}
