116:000116 | 	private void shutdownDatabase(ServletContext context) {
117:000117 | 		if (dataSource == null) return;
118:000118 | 		Connection connection = null;
119:000119 | 		Statement statement = null;
120:000120 | 		try {
121:000121 | 			connection = dataSource.getConnection();
