11:/** Access 年金データ Excel 出力の Open XML 置換。 */
12:public final class PensionExcelExportService {
13:    public static final String CONTENT_TYPE =
14:            "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
15:
16:    private static final PensionExcelExportService INSTANCE =
17:            new PensionExcelExportService(PensionRepository.getInstance());
18:
19:    private final PensionRepository repository;
20:
21:    public PensionExcelExportService() {
22:        this(PensionRepository.getInstance());
23:    }
24:
25:    public PensionExcelExportService(PensionRepository repository) {
26:        if (repository == null) {
27:            throw new IllegalArgumentException("repositoryはnullにできません。");
28:        }
29:        this.repository = repository;
30:    }
31:
32:    public static PensionExcelExportService getInstance() {
33:        return INSTANCE;
34:    }
35:
36:    public PensionExcelExportResult buildByBranch(int branchNo) {
37:        List<PensionReservation> reservations = repository.listByBranch(branchNo);
38:        if (reservations.isEmpty()) {
39:            return new PensionExcelExportResult("", new byte[0], 0);
40:        }
41:
42:        List<String> headers = Arrays.asList(
43:                "顧客番号", "担\n当", "顧客氏名", "ふりがな", "性\n別", "住所",
44:                "電話番号", "生年月日", "年金種類", "裁定\n請求", "受給\n有無",
45:                "請求予定日", "予定\n年齢", "配偶者名", "配偶者\n生年月日",
46:                "予約徴求日", "備考", "６ヶ月先\n確認");
47:        List<Object[]> rows = new ArrayList<Object[]>();
48:        for (int i = 0; i < reservations.size(); i++) {
49:            PensionReservation row = reservations.get(i);
50:            rows.add(new Object[] {
51:                row.getCustomerNo(), row.getStaffCode(), row.getCustomerName(), row.getKanaName(),
52:                row.getGender(), row.getAddress(), row.getPhoneNumber(), row.getBirthDate(),
53:                row.getPensionType(), row.getClaimStatus(), row.getHasBenefit(),
54:                row.getClaimScheduledDate(), row.getPlannedAge(), row.getSpouseName(),
55:                row.getSpouseBirthDate(), row.getReservationRequestDate(), row.getNotes(),
56:                row.isSixMonthCheck() ? "確" : ""
57:            });
58:        }
59:
60:        String compactDate = DateUtil.todayIso().replace("-", "");
61:        String fileName = "年金データ_" + threeDigits(branchNo) + "_" + compactDate + ".xlsx";
62:        byte[] content = OpenXmlWorkbookWriter.buildWorkbook("年金ﾃﾞｰﾀ", headers, rows);
63:        return new PensionExcelExportResult(fileName, content, rows.size());
64:    }
65:
66:    private static String threeDigits(int value) {
67:        String text = Integer.toString(value);
68:        while (text.length() < 3) {
69:            text = "0" + text;
70:        }
71:        return text;
72:    }
73:}

