sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:27:	public static String formatJapaneseDate(String value) {
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:28:		Date date = parseIso(value);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:29:		if (date == null) return value(value);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:30:		Calendar target = Calendar.getInstance();
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:31:		target.setTime(date);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:32:		int year = target.get(Calendar.YEAR);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:33:		int month = target.get(Calendar.MONTH) + 1;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:34:		int day = target.get(Calendar.DAY_OF_MONTH);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:35:		String symbol;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:36:		int eraYear;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:37:		if (!date.before(parseIso("2019-05-01"))) { symbol = "R"; eraYear = year - 2018; }
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:38:		else if (!date.before(parseIso("1989-01-08"))) { symbol = "H"; eraYear = year - 1988; }
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:39:		else if (!date.before(parseIso("1926-12-25"))) { symbol = "S"; eraYear = year - 1925; }
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:40:		else if (!date.before(parseIso("1912-07-30"))) { symbol = "T"; eraYear = year - 1911; }
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:41:		else if (!date.before(parseIso("1868-09-08"))) { symbol = "M"; eraYear = year - 1867; }
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:42:		else return formatWesternDate(value);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:43:		return symbol + " " + two(eraYear) + "/" + two(month) + "/" + two(day);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:44:	}
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:45:
