sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:51:	public static String json(String value) {
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:52:		if (value == null) return "";
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:53:		StringBuilder result = new StringBuilder();
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:54:		for (int i = 0; i < value.length(); i++) {
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:55:			char c = value.charAt(i);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:56:			switch (c) {
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:57:			case '\\': result.append("\\\\"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:58:			case '"': result.append("\\\""); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:59:			case '\r': result.append("\\r"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:60:			case '\n': result.append("\\n"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:61:			case '\t': result.append("\\t"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:62:			case '\b': result.append("\\b"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:63:			case '\f': result.append("\\f"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:64:			case '<': result.append("\\u003c"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:65:			case '>': result.append("\\u003e"); break;
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:66:			default:
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:67:				if (c < 0x20 || c == '\u2028' || c == '\u2029') result.append(String.format("\\u%04x", Integer.valueOf(c)));
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:68:				else result.append(c);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:69:			}
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:70:		}
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:71:		return result.toString();
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:72:	}
