sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:77:		format.setLenient(false);
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:78:		try { return format.parse(value.trim()); } catch (ParseException e) { return null; }
sources/nenkin/WEB-INF/src/nenkin/util/HtmlUtil.java:79:	}
